#!/usr/bin/env bash
#
# Generated-artifact drift guard.
#
# Two artifacts under apps/mdreader/ui/src are GENERATED by the desktop crate's
# tests and committed to the repo; they must never drift from their Rust source
# of truth:
#   - bindings.ts          — the tauri-specta TypeScript command surface;
#   - goldens/provenance.json — a real hybrid-search hit's start_line for the
#                            fixture corpus, which the reader's TS golden test
#                            reads (the one line value crossing Rust→TS).
#
# This regenerates both headlessly (no window, no webview, no dev server) by
# running the crate's library tests, then fails if the working tree changed. CI
# runs this to reject PRs whose generated artifacts weren't regenerated after a
# command-surface or chunker change.
#
# Usage: ./scripts/check-bindings.sh
set -euo pipefail

script_dir="$(cd "$(dirname "$0")" && pwd)"
repo_root="$(cd "$script_dir/.." && pwd)"

cd "$repo_root"

# The lib tests write both artifacts as a side effect: `export_bindings_up_to_date`
# emits bindings.ts, and the search provenance test emits goldens/provenance.json.
# `--quiet` keeps CI logs readable; a generation failure panics (non-zero).
cargo test --package mdreader-app --lib --quiet

git diff --exit-code -- \
  apps/mdreader/ui/src/bindings.ts \
  apps/mdreader/ui/src/goldens/provenance.json
